import { createFormHook, createFormHookContexts } from "@tanstack/react-form";
import React from "react";

import { DSButton } from "#src/app/design-system/button.js";
import { DSInput } from "#src/app/design-system/input.js";

const { fieldContext, formContext, useFieldContext, useFormContext } = createFormHookContexts();

type TextFieldProps = {
  sx?: { label?: string; input?: string };
  autoComplete?: React.ComponentProps<"input">["autoComplete"];
  disabled?: boolean;
  label: string;
  maxLength?: number;
  placeholder?: string;
  required?: boolean;
  type?: "email" | "password" | "text" | "url";
  hideLabel?: boolean;
};

function TextField({
  sx,
  autoComplete,
  disabled,
  label,
  maxLength,
  placeholder,
  required,
  type = "text",
  hideLabel = false,
}: TextFieldProps): React.JSX.Element {
  const field = useFieldContext<string>();
  const errorMessage = field.state.meta.isBlurred
    ? getErrorMessage(field.state.meta.errors[0])
    : undefined;

  return (
    <DSInput
      sx={sx}
      autoComplete={autoComplete}
      disabled={disabled}
      label={label}
      maxLength={maxLength}
      placeholder={placeholder}
      required={required}
      type={type}
      hideLabel={hideLabel}
      errorMessage={errorMessage}
      name={field.name}
      value={field.state.value}
      onBlur={field.handleBlur}
      onChange={(event) => field.handleChange(event.target.value)}
    />
  );
}

type SubmitButtonProps = {
  sx?: { button: string };
  disabled?: boolean;
  disabledWhenPristine?: boolean;
  label: string;
  submittingLabel?: string;
};

function SubmitButton({
  sx,
  disabled = false,
  disabledWhenPristine = false,
  label,
  submittingLabel = label,
}: SubmitButtonProps): React.JSX.Element {
  const form = useFormContext();

  return (
    <form.Subscribe
      selector={(state) => [state.canSubmit, state.isPristine, state.isSubmitting] as const}
    >
      {([canSubmit, isPristine, isSubmitting]) => (
        <DSButton
          className={sx?.button}
          disabled={disabled || !canSubmit || (disabledWhenPristine && isPristine)}
          isPending={isSubmitting}
          type="submit"
          variant="contained"
        >
import { css } from "@linaria/core";
import React from "react";

import { composeClassnames, visuallyHidden } from "#src/app/utils.js";

type DSInputProps = {
  errorMessage?: string | undefined;
  name?: string;
  value?: React.ComponentProps<"input">["value"];
  onBlur?: React.ComponentProps<"input">["onBlur"];
  onChange?: React.ComponentProps<"input">["onChange"];
  sx?: { label?: string; input?: string } | undefined;
  autoComplete?: React.ComponentProps<"input">["autoComplete"];
  disabled?: boolean | undefined;
  label: string;
  maxLength?: number | undefined;
  placeholder?: string | undefined;
  required?: boolean | undefined;
  type?: "email" | "password" | "text" | "url";
  hideLabel?: boolean | undefined;
};

export function DSInput({
  sx,
  autoComplete,
  disabled,
  label,
  maxLength,
  placeholder,
  required,
  type = "text",
  hideLabel = false,
  errorMessage,
  name,
  value,
  onBlur,
  onChange,
}: DSInputProps): React.JSX.Element {
  const inputId = React.useId();
  const errorId = `${inputId}-error`;

  return (
    <label
