cat > apps/web-app/src/app/design-system/design-system.story.tsx <<'EOF'
import { css } from "@linaria/core";
import React from "react";

import { DSButton } from "#src/app/design-system/button.js";
import { DSInput } from "#src/app/design-system/input.js";

export function AllVariants(): React.ReactNode {
  const [clickCount, setClickCount] = React.useState(0);

  return (
    <main>
      <h1>Design system</h1>
      <h2>Buttons</h2>
      <div className={grid}>
        {(["outlined", "contained", "text"] as const).map((variant) => (
          <section key={variant} aria-label={`${variant} buttons`} className={grid}>
            <h3>{variant}</h3>
            <DSButton variant={variant} onClick={() => setClickCount((count) => count + 1)}>
              Record click
            </DSButton>
            <DSButton variant={variant} disabled>Disabled</DSButton>
            <DSButton variant={variant} isPending>Working</DSButton>
          </section>
        ))}
      </div>
      <p role="status">Clicks: {clickCount}</p>
      <h2>Inputs</h2>
      <div className={grid}>
        <DSInput label="Text" placeholder="Enter text" />
        <DSInput label="Email" type="email" placeholder="you@example.com" />
        <DSInput label="Password" type="password" placeholder="Enter a password" />
        <DSInput label="URL" type="url" placeholder="https://example.com" />
        <DSInput label="Required" required placeholder="Required text" />
        <DSInput label="Disabled" disabled value="Disabled input" />
        <DSInput label="Invalid" errorMessage="Please enter a valid value." />
        <DSInput label="Hidden label" hideLabel placeholder="Hidden label" />
      </div>
    </main>
  );
}

const grid = css`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: calc(3 * var(--spacing-base));
  align-items: start;
`;
EOF
cat > apps/web-app/src/app/design-system/design-system.test.ts <<'EOF'
import { expect, test } from "@playwright/test";

test("renders all design system variants", async ({ mount }) => {
  const component = await mount("app/design-system/design-system/AllVariants");

  await expect(component).toHaveScreenshot("design-system.png");
});

test("records button clicks and renders disabled states", async ({ mount }) => {
  const component = await mount("app/design-system/design-system/AllVariants");

  for (const variant of ["outlined", "contained", "text"]) {
    const section = component.getByRole("region", { name: `${variant} buttons` });
    await expect(section.getByRole("button", { name: "Record click" })).toHaveAttribute("data-variant", variant);
    await expect(section.getByRole("button", { name: "Disabled" })).toBeDisabled();
    await expect(section.getByRole("button", { name: "Working" })).toBeDisabled();
    await section.getByRole("button", { name: "Record click" }).click();
  }

  await expect(component.getByRole("status")).toHaveText("Clicks: 3");
});

test("supports input interaction and accessible errors", async ({ mount }) => {
  const component = await mount("app/design-system/design-system/AllVariants");

  await component.getByLabel("Text", { exact: true }).fill("Example text");
  await expect(component.getByLabel("Text", { exact: true })).toHaveValue("Example text");
  await expect(component.getByLabel("Disabled", { exact: true })).toBeDisabled();
  await expect(component.getByLabel("Invalid", { exact: true })).toHaveAccessibleDescription("Please enter a valid value.");
  await expect(component.getByLabel("Hidden label", { exact: true })).toBeVisible();
});
EOF
pnpm exec oxfmt apps/web-app/src/app/design-system/design-system.story.tsx apps/web-app/src/app/design-system/design-system.test.ts
pnpm --filter @cup/web-app test:components --update-snapshots > /tmp/design-system-playwright.log 2>&1

