import { css } from "@linaria/core";
import { useNavigate } from "@tanstack/react-router";
import React from "react";

import { type GrantSnapshot, startConversionRequestSchema } from "@cup/web-app-api.routes";

import { MovingEllipse } from "#src/app/components/moving-ellipse.js";
import { useAppForm } from "#src/app/form.js";
import { useStartConversionMutation } from "#src/data-fetching/trial-link.js";
import { subscribeToSharedUrl } from "#src/platform/share-intake.js";

export function StartConversionForm({ grant }: { grant: GrantSnapshot }): React.JSX.Element {
  const navigate = useNavigate();
  const startConversionMutation = useStartConversionMutation(grant.grantId);
  const form = useAppForm({
    defaultValues: { sourceUrl: "" },
    validators: {
      onBlur: startConversionRequestSchema,
      onChange: startConversionRequestSchema,
      onSubmit: startConversionRequestSchema,
    },
    onSubmit: async ({ value }) => {
      const result = await startConversionMutation.mutateAsync({
        sourceUrl: value.sourceUrl,
        idempotencyKey: crypto.randomUUID(),
      });
      form.reset();
      await navigate({
        to: "/conversions/$conversionId",
        params: { conversionId: result.conversion.conversionId },
      });
    },
  });

  React.useEffect(() => {
    return subscribeToSharedUrl((url) => form.setFieldValue("sourceUrl", url));
  }, [form]);

  return (
    <form
      className={css`
        position: relative;
        display: grid;
        gap: calc(3 * var(--spacing-base));
        padding-block: calc(5 * var(--spacing-base));
        padding-inline: calc(2 * var(--spacing-base));
        background: var(--color-surface-translucent);
        border-radius: var(--border-radius-lg);
      `}
      onSubmit={(event) => {
        event.preventDefault();
        event.stopPropagation();
        void form.handleSubmit();
      }}
    >
      <MovingEllipse />
      <form.AppForm>
        <form.AppField name="sourceUrl">
          {(field) => (
            <field.TextField
              sx={{
                input: css`
                  height: 64px;
                  padding-inline: 24px;
                  font-family: var(--font-family-1);
                  font-size: var(--font-size-md);
                  /* Reveal the moving ellipse only through the transparent border. */
                  background: var(--color-input-bg) padding-box;
                  backdrop-filter: saturate(6);

                  &::placeholder {
                    color: var(--color-fg-emphasized-sm);
                  }
                `,
              }}
              label="URL"
              maxLength={2048}
              required
              type="url"
              placeholder="Paste URL here"
              hideLabel
            />
          )}
        </form.AppField>
        <form.SubmitButton
          sx={{
            button: css`
              justify-self: end;
            `,
          }}
          disabledWhenPristine
          label="Load & listen"
          submittingLabel="Starting conversion..."
        />
      </form.AppForm>
    </form>
  );
}
import { css } from "@linaria/core";
import React from "react";

import { composeClassnames, visuallyHidden } from "#src/app/utils.js";

export type DSInputProps = {
  errorMessage?: string | undefined;
  name?: string;
  value?: React.ComponentProps<"input">["value"];
  onBlur?: React.ComponentProps<"input">["onBlur"];
  onChange?: React.ComponentProps<"input">["onChange"];
  sx?: { label?: string; input?: string } | undefined;
  autoComplete?: React.ComponentProps<"input">["autoComplete"];
  disabled?: boolean | undefined;
  label: string;
  maxLength?: number | undefined;
  placeholder?: string | undefined;
  required?: boolean | undefined;
  type?: "email" | "password" | "text" | "url";
  hideLabel?: boolean | undefined;
};

export function DSInput({
  sx,
  autoComplete,
  disabled,
  label,
  maxLength,
  placeholder,
  required,
  type = "text",
  hideLabel = false,
  errorMessage,
  name,
  value,
  onBlur,
  onChange,
}: DSInputProps): React.JSX.Element {
  const inputId = React.useId();
  const errorId = `${inputId}-error`;

  return (
    <label
      className={composeClassnames(
        css`
          display: flex;
          flex-direction: column;
          gap: calc(0.5 * var(--spacing-base));
        `,
        sx?.label,
      )}
    >
      <span className={hideLabel ? visuallyHidden : undefined}>{label}</span>
      <input
        className={composeClassnames(
          css`
            padding-block: calc(1.5 * var(--spacing-base));
            padding-inline: calc(2.5 * var(--spacing-base));

            font-size: 18px;
            color: var(--color-fg);
            border: 2px solid transparent;
            border-radius: 999px;
            box-shadow: 4px 4px 20px rgb(0 0 0 / 12%);

            &:focus-visible {
              border-radius: 999px;
            }

            &::placeholder {
              color: var(--color-fg-emphasized-xs);
            }
          `,
          sx?.input,
        )}
        aria-describedby={errorMessage === undefined ? undefined : errorId}
        aria-invalid={errorMessage === undefined ? undefined : true}
        autoComplete={autoComplete}
        disabled={disabled}
        id={inputId}
        maxLength={maxLength}
        name={name}
        placeholder={placeholder}
        required={required}
        type={type}
        value={value}
        onBlur={onBlur}
        onChange={onChange}
      />
      {errorMessage === undefined ? null : (
        <small
          className={css`
            color: var(--color-error);
          `}
          id={errorId}
          role="alert"
        >
          {errorMessage}
        </small>
      )}
    </label>
  );
}

